<script>
  import { computeLogisticRegression } from '@/lib/formula-lessons/part4-models.mjs';
  export let lesson; export let spec; let w1=spec.x[0],w2=spec.x[1],beta=spec.beta;
  $: result=computeLogisticRegression({samples:spec.samples,x:[Number(w1),Number(w2)],beta:Number(beta)}); const f=(v,d=4)=>Number(v).toFixed(d); const px=v=>170+v*95,py=v=>145-v*95; $: boundary=Math.abs(Number(w2))>1e-6?{x1:px(-1.45),y1:py(-Number(w1)*(-1.45)/Number(w2)),x2:px(1.45),y2:py(-Number(w1)*1.45/Number(w2))}:{x1:px(0),y1:15,x2:px(0),y2:275};
</script>
<div class="lesson-grid" data-part4-logistic data-focus={lesson.focus}><section class="panel"><p class="eyebrow">margin + decision boundary</p><svg viewBox="0 0 340 290" role="img" aria-label="logistic regression samples and boundary"><line class="axis" x1="20" y1="145" x2="320" y2="145"/><line class="axis" x1="170" y1="15" x2="170" y2="275"/><line class="boundary" x1={boundary.x1} y1={boundary.y1} x2={boundary.x2} y2={boundary.y2}/>{#each result.samples as sample,i (i)}<circle class:positive={sample.y===1} class:negative={sample.y===-1} cx={px(sample.v[0])} cy={py(sample.v[1])} r="7"><title>margin {f(result.margins[i],3)}</title></circle>{/each}</svg><label>w₁ <output>{f(w1,2)}</output><input bind:value={w1} type="range" min="-1.5" max="1.5" step=".05"/></label><label>w₂ <output>{f(w2,2)}</output><input bind:value={w2} type="range" min="-1.5" max="1.5" step=".05"/></label><label>β <output>{f(beta,2)}</output><input bind:value={beta} type="range" min="0" max=".8" step=".02"/></label></section><section class="panel"><p class="eyebrow">same weights: loss · gradient · curvature</p><div class="metrics"><div><span>objective</span><strong>{f(result.objective)}</strong></div><div><span>regularizer</span><strong>{f(result.regularizer)}</strong></div><div><span>max σ(1-σ)</span><strong>{f(result.maxCurvature)}</strong></div><div><span>≤1/4</span><strong>{result.curvatureBoundHolds?'PASS':'FAIL'}</strong></div><div><span>L upper</span><strong>{f(result.practicalLipschitzUpper)}</strong></div><div><span>all margins +?</span><strong>{result.decisions.every(Boolean)?'YES':'NO'}</strong></div></div><p class="vector">∇Ψ=[{result.grad.map(v=>f(v,4)).join(', ')}]</p><div class="table-wrap"><table><thead><tr><th>m</th><th>y</th><th>margin</th><th>loss</th></tr></thead><tbody>{#each result.samples as sample,i (i)}<tr><td>{i+1}</td><td>{sample.y}</td><td>{f(result.margins[i],3)}</td><td>{f(result.losses[i],4)}</td></tr>{/each}</tbody></table></div><p class="note">183/184 source mapping blanks stay separate from 210 completion; 182 curvature feeds the practical L bound.</p></section></div>
<style>.lesson-grid{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}.panel{border:1px solid var(--color-border);border-radius:1rem;background:var(--color-background);padding:1rem}.eyebrow{margin:0 0 .5rem;font-size:.66rem;font-weight:900;text-transform:uppercase;letter-spacing:.1em;color:var(--color-muted-foreground)}svg{width:100%;max-height:18rem}.axis{stroke:var(--color-border)}.boundary{stroke:var(--color-primary);stroke-width:3;stroke-dasharray:7 5}circle{stroke:var(--color-background);stroke-width:2}.positive{fill:var(--color-primary)}.negative{fill:var(--color-foreground)}label{display:grid;grid-template-columns:1fr auto;margin-top:.4rem;font-size:.72rem;font-weight:800}input{grid-column:1/-1;min-height:30px}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:.4rem}.metrics div{display:grid;background:var(--color-muted);border-radius:.65rem;padding:.55rem;font-size:.72rem}.metrics span{color:var(--color-muted-foreground)}.vector{font-family:ui-monospace,monospace;font-size:.74rem}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:.68rem}th,td{padding:.38rem;border-bottom:1px solid var(--color-border);text-align:right}.note{font-size:.73rem;line-height:1.65;color:var(--color-muted-foreground)}@media(max-width:760px){.lesson-grid{grid-template-columns:1fr}}</style>
